CREATE OR REPLACE FUNCTION b.throw_error()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'Nope.';
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION c.badly_behaved_function()
 RETURNS SETOF c.person
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return query select * from c.person order by id asc limit 1;
  return next null;
  return query select * from c.person order by id desc limit 1;
end;
$function$

CREATE OR REPLACE FUNCTION c.issue756_set_mutation()
 RETURNS SETOF c.issue756
 LANGUAGE plpgsql
AS $function$
begin
  return query insert into c.issue756 default values returning *;
  return next null;
  return query insert into c.issue756 default values returning *;
end;
$function$

CREATE OR REPLACE FUNCTION c.query_output_two_rows(left_arm_id integer, post_id integer, INOUT txt text, OUT left_arm c.left_arm, OUT post a.post)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  txt = txt || left_arm_id::text || post_id::text;
  select * into $4 from c.left_arm where id = left_arm_id;
  select * into $5 from a.post where id = post_id;
end;
$function$

